      id: u.getUnitID(), type, x: u.getX(), y: u.getY(), hp: u.getCurrentHP(),
      airDamageBonus: snakeAirBonus ? u.getFieldValue('dmgModifierAddition')[0] : 0,
      maxHP: val('hp'), regeneration: val('hpRegenerationRate'), lifesteal, damage: val('dmg'), armor: val('armor'), penetration: val('armorPenetration') || 0,
      damageFloor: val('dmgCap') || 1, radius: val('radius') || 0.5,
      range: val('range'), minRange: val('minRange') || 0, speed: (val('movementSpeed') || 0) * 20,
      cooldown: val('weaponCooldown') || 20, delay: val('weaponDelay') || 0,
      windup: lastHit >= Math.round(now * 20) - 1 ? u.getValue('hitCycle') || 0 : 0,
      ready: Math.max(0, (u.getValue('tickOfLastWeaponFired') ?? -999) + (val('weaponCooldown') || 20) - now * 20),
      projectileSpeed: val('projectileSpeed') || 0, splash: val('aoeRadius') || 0,
      seeking: !!val('isHeatSeeking'), friendlyFire: !!val('hitsFriendly'),
      flying: !!val('isFlying'), ground: !!val('canAttackGround'), air: !!val('canAttackFlying'),
      building: !!u.getFieldValue('isBuilding'), cost: val('cost') || 50,
      supported: ['Worker', 'Soldier', 'Archer', 'Wolf', 'Snake', 'Catapult', 'Watchtower', 'Watchtower (detection)', 'Castle', 'House', 'Barracks', 'Workshop', 'Forge'].indexOf(type) >= 0 &&
        (!bonusTags.length || snakeAirBonus) && !val('bouncePower') &&
        !(u.getValue('shields') || []).length && !(u.getValue('modifiers') || []).length && !(u.getFieldValue('modifiers') || []).length &&
        !val('isInvincible') && !val('hitscan') && (!lifesteal || (type === 'Wolf' && lifesteal === 0.01)) && !val('percDmg') && !val('attackConeAngle'),
