      let score = (b.damage > 0 ? 40 : 0) - d * 3 - b.hp / Math.max(b.maxHP, 1);
      if (a.splash) score += enemies.filter(e => e.hp > 0 && distance(e, b) <= a.splash + e.radius).length * 12;
      if (d <= a.range) score += 25;
