// Compare whole allocations. Each forecast starts defenders at their real positions.
// An Archer sent across the map is absent from the donor's simulated fight.
function allocateDefenders(groups, previous) {
  if (groups.length < 2) return null;
  const contacts = groups.map(g => {
    const attackers = g.threats.slice(0,16);
    const assets = g.workers.slice(0,16).map(w=>({...w,damage:0}))
      .concat(g.structures.slice(0,4).map(b=>({...b,protectedAsset:true})));
    return {g,attackers,assets,pressure:attackers.reduce((sum,e)=>sum+P.power(e),0),
      routes:new Map(),costs:new Map()};
  });
  const units = new Map();
  for (const site of contacts) {
    const nearby = own.map(u=>ownSnapshots[id(u)]).filter(a=>a.type!=='Worker' && a.damage>0 &&
      dist(a,site.g.point)<36).sort((a,b)=>dist(a,site.g.point)-dist(b,site.g.point)||a.id-b.id);
    for (const a of nearby) {
      const targets = site.attackers.filter(e=>e.flying?a.air:a.ground)
        .sort((l,r)=>P.edge(a,l)-P.edge(a,r)||l.id-r.id);
      let eta=Infinity;
      for(const e of targets) {
        const gap=P.edge(a,e);
        if(gap<=a.range && gap>=a.minRange){eta=0;break;}
        const to=reachableFrom(byID[a.id],e.x,e.y);
        if(!to || dist(to,e)>a.range+a.radius+e.radius+1) continue;
        eta=Math.max(0,gap-a.range,a.minRange-gap)/Math.max(0.1,a.speed);
        break;
      }
      if(!Number.isFinite(eta)) continue;
      units.set(a.id,a);
      const continuing=Object.values(previous).some(plan=>plan.progress.some(p=>
        p.id===a.id && site.attackers.some(e=>e.id===p.target)));
      site.routes.set(a.id,{eta,continuing});
      if(site.routes.size===16) break;
    }
  }
  if(!contacts.some((s,i)=>contacts.slice(i+1).some(other=>
    Array.from(s.routes.keys()).some(k=>other.routes.has(k))))) return null;

  const guards=Array.from(units.values()).sort((a,b)=>a.id-b.id);
  function propose(balance,keep) {
    const plan=contacts.map(()=>[]);
    const strength=contacts.map(()=>0);
    for(const a of guards){
      let best=-1,lowest=Infinity;
      contacts.forEach((site,i)=>{
        const route=site.routes.get(a.id);
        if(!route) return;
        const cost=route.eta-(route.continuing?keep:0)+balance*strength[i]/Math.max(1,site.pressure);
        if(cost<lowest){lowest=cost;best=i;}
      });
      plan[best].push(a);
      strength[best]+=P.power(a);
    }
    return plan;
  }
  function cost(site,team) {
    const key=team.map(a=>a.id).join(',');
    if(site.costs.has(key)) return site.costs.get(key);
    const config={...C.predictor,horizonTicks:320,stepTicks:5,protectAssets:true};
    const fight=P.simulate(team.concat(site.assets),site.attackers,'approach',site.g.point,config);
    S.stats.predictionCalls++;
    let firstCover=16,travel=0;
    for(const a of team){
      const r=site.routes.get(a.id);
      firstCover=Math.min(firstCover,r.eta);
      travel+=r.eta*(r.continuing?0.5:1);
    }
    if(site.assets.some(b=>b.building && b.damage>0 && site.attackers.some(e=>
      (e.flying?b.air:b.ground) && P.edge(b,e)<=b.range))) firstCover=0;
    const value=100*fight.deadWorkers.length+160*Number(fight.lostBuilding)+fight.losses[0]-
      0.35*fight.losses[1]+firstCover*Math.min(10,site.assets.length)+travel;
    site.costs.set(key,value);
    return value;
  }
  let best,minimum=Infinity;
  for(const [balance,keep] of [[0,4],[5,3],[12,2],[5,0]]){
    const plan=propose(balance,keep);
    const score=plan.reduce((sum,team,i)=>sum+cost(contacts[i],team),0);
    if(score<minimum){minimum=score;best=plan;}
  }
  return new Map(groups.map((group,i)=>[group,new Set(best[i].map(a=>a.id))]));
}

// Reserve the response before either opening assigns scouts, escorts or raiders.
function defendAssets() {
  const previous = S.assetDefence || {};
  S.assetDefence = {};
  S.evacuatingWorkers = {};
  S.guardTargets = {};
  const assigned = new Set(), managedWorkers = new Set(), handled = new Set();
  const result = {assigned, managedWorkers, handled, archers:[], assisting:new Set()};
  const workSites = S.pullWorkSites || (S.pullWorkSites = {});
  for (const key of Object.keys(workSites)) {
    const w = byID[key];
    if (!w || (w.getCurrentOrderName() === 'Mine' && (dist(pos(w),workSites[key]) < 3 ||
      mines.some(m => id(m) === S.jobMines[key] && dist(pos(w),pos(m)) < 3)))) delete workSites[key];
  }
  const enemyById = new Map(enemyWrappers.concat(enemyBuildings).map(u=>[id(u),u]));
  const hostiles = visible.filter(e => e.damage > 0 && e.ground && (e.type !== 'Worker' ||
    ['Attack','AMove'].includes(enemyById.get(e.id).getCurrentOrderName())));
  if (!hostiles.length) return result;
  const structures = buildings.map(u=>ownSnapshots[id(u)] || P.snapshot(u,now));
  const assets = workers.map(w=>ownSnapshots[id(w)]).concat(structures);
  const injuries = new Map();
  for (const a of assets) {
    const hit=byID[a.id].getLastAttack();
    if(hit && now-hit.time<3) injuries.set(a.id,hit);
  }
  const groups=[];
  for (const e of hostiles) {
    let victim, best=Infinity;
    const currentTarget=enemyById.get(e.id).getValue('targetUnit')?.id;
    for (const a of assets) {
      // A pursuing Worker cannot move the site it was pulled to defend.
      if (workSites[a.id] && dist(workSites[a.id],e) > 12) continue;
      const gap=P.edge(e,a)-e.range;
      if (gap>6) continue;
      const injury=injuries.get(a.id);
      const score=gap-(injury && dist(injury,e)<4 ? 7:0)-(a.id===currentTarget?4:0);
      if(score<best || (score===best && a.id<victim.id)){best=score;victim=a;}
    }
    if(!victim) continue;
    let g=groups.find(other=>dist(other.point,victim)<11);
    if(!g){g={point:victim, threats:[], workers:[], structures:[], urgency:best};groups.push(g);}
    g.threats.push(e);g.urgency=Math.min(g.urgency,best);
    handled.add(e.id);
    const base=nearestThreatBase[e.id];
    if(base) base.defenseDemand-=observedPower(e);
  }
  if(!groups.length) return result;
  // Assign each asset once, including mines between two simultaneous fights.
  for(const a of assets) {
    const g=groups.filter(site=>site.threats.some(e=>P.edge(e,a)<=e.range+9))
      .sort((x,y)=>dist(x.point,a)-dist(y.point,a)||x.point.id-y.point.id)[0];
    if(g) (a.building?g.structures:g.workers).push(a);
  }
  groups.sort((a,b)=>a.urgency-b.urgency || b.workers.length-a.workers.length || a.point.id-b.point.id);
  const allocation=allocateDefenders(groups,previous);
  for(const g of groups) {
    const nearestEnemy=a=>Math.min(...g.threats.map(e=>P.edge(e,a)-e.range));
    const priority=(a,b)=>nearestEnemy(a)-nearestEnemy(b)||a.hp-b.hp||a.id-b.id;
    g.workers.sort(priority);g.structures.sort(priority);
    const contact=g.threats.slice().sort((a,b)=>dist(a,g.point)-dist(b,g.point)||a.id-b.id);
    const previousPlan=previous[contact.reduce((v,e)=>Math.min(v,e.id),Infinity)];
    const stalled=new Set((previousPlan?.progress || []).filter(p=>now-p.since>=4).map(p=>p.id));
    const candidates=own.map(u=>ownSnapshots[id(u)]).filter(a=>a.type!=='Worker' && a.damage>0 && !assigned.has(a.id) &&
      (!allocation || allocation.get(g).has(a.id)) &&
      dist(a,g.point)<36 && contact.some(e=>e.flying?a.air:a.ground))
      .sort((a,b)=>Number(stalled.has(a.id))-Number(stalled.has(b.id)) || nearestEnemy(a)/a.speed-nearestEnemy(b)/b.speed || a.id-b.id)
      .filter(a=>contact.some(e=>{
        if(P.edge(a,e)<=a.range) return true;
        const to=reachableFrom(byID[a.id],e.x,e.y);
        return to && dist(to,e)<=a.range+a.radius+e.radius+1;
      })).slice(0,16);
    // Fixed bounds keep multiplayer work deterministic. An unsampled Worker
    // prevents a partial loss forecast from authorising a site-wide withdrawal.
    const miners=g.workers.slice(0,16);
    const staticAssets=g.structures.slice(0,4).map(a=>({...a,protectedAsset:true}));
    const opponents=contact.slice(0,16);
    const config={...C.predictor,horizonTicks:320,stepTicks:5,protectAssets:true,workerRetreatFraction:0.45};
    const buildingUnderAttack=staticAssets.some(a=>injuries.has(a.id) ||
      contact.some(e=>enemyById.get(e.id).getValue('targetUnit')?.id===a.id));
    let calls=0;
    const forecast=(count,assist)=>{
      const crew=miners.map(a=>{
        const helper=assist && !usedWorkers[a.id] && !/^Build |^Repair$/.test(byID[a.id].getCurrentOrderName()||'');
        const mine=helper && escapeMine(byID[a.id],contact,true);
        return {...a,damage:helper?a.damage:0,mineralRetreat:mine?pos(mine):null};
      });
      const guards=candidates.slice(0,count).map(a=>stalled.has(a.id)?{...a,ready:Math.max(a.ready,80)}:a);
      const ownSide=guards.concat(crew,staticAssets);
      calls++;
      const fight=P.simulate(ownSide,opponents,'approach',g.point,config);
      if(buildingUnderAttack && crew.length && !assist && !fight.lostBuilding) {
        calls++;
        fight.lostBuilding=P.simulate(ownSide,opponents,'approach',g.point,{...config,prioritiseBuildings:true}).lostBuilding;
      }
      return fight;
    };
    const cleared=f=>!f.alive[1] && !f.deadWorkers.length && !f.lostBuilding;
    let required=candidates.length, mining=forecast(required,false);
    if(cleared(mining)){
      let lo=0,hi=required;
      while(lo<hi){
        const mid=Math.floor((lo+hi)/2), f=forecast(mid,false);
        if(cleared(f)){hi=mid;mining=f;} else lo=mid+1;
      }
      required=lo;
    }
    const selected=candidates.slice(0,required), progress=[];
    let engaging=0,inRange=0;
    for(const a of selected){
      const u=byID[a.id];
      const target=P.target(a,contact,observations);
      if(!target) continue;
      const gap=P.edge(a,target);
      const last=u.getValue('tickOfLastWeaponFired');
      const old=previousPlan?.progress.find(p=>p.id===a.id && p.target===target.id);
      // Confirm that this unit fired on this assignment, or is closing range.
      const fired=old && last>old.last && u.getValue('targetUnit')?.id===target.id;
      if(fired) engaging++;
      if(gap<=a.range) inRange++;
      const since=!old || fired || gap<old.best-0.5 ? now:old.since;
      progress.push({id:a.id,target:target.id,last,best:since===now?gap:old.best,since});
      assigned.add(a.id);S.guardTargets[a.id]=target.id;
      if(a.type==='Archer') {
        result.archers.push({a,target,victim:enemyById.get(target.id),contact,point:g.point,stalled:stalled.has(a.id)});
        continue;
      }
      if(gap<a.minRange || (stalled.has(a.id) && gap>a.range)) {
        const step=gap<a.minRange?{x:a.x+(a.x-target.x),y:a.y+(a.y-target.y)}:target;
        move(u,step);
      } else order('Attack',[u],{unit:enemyById.get(target.id)},2);
    }
    let mode='mine',help,evading=0;
    const dead=new Set(mining.deadWorkers);
    const ground=contact.filter(e=>!e.flying);
    if(dead.size && ground.length) {
      help=forecast(required,true);
      mode=help.deadWorkers.length===g.workers.length?'withdraw':'assist';
    } else if(dead.size) mode='evade';
    for(const a of g.workers) {
      const w=byID[a.id];
      managedWorkers.add(a.id);
      if(usedWorkers[a.id] || /^Build |^Repair$/.test(w.getCurrentOrderName()||'')) continue;
      const weak=a.hp<=a.maxHP*config.workerRetreatFraction;
      if(mode==='mine' || (mode==='evade'&&!dead.has(a.id))) continue;
      if(mode==='assist' && !weak && !(dead.has(a.id) && contact.every(e=>e.flying || P.edge(a,e)>9))) {
        const foe=P.target(a,ground,observations);
        if(foe){
          result.assisting.add(a.id);
          workSites[a.id] ||= pos(w);
          order('Attack',[w],{unit:enemyById.get(foe.id)},2);
          usedWorkers[a.id]=true;
          continue;
        }
      }
      if(evadeRaid(w,contact,mode==='assist')){usedWorkers[a.id]=true;S.evacuatingWorkers[a.id]=now;evading++;}
    }
    S.stats.predictionCalls+=calls;
    S.assetDefence[Math.min(...contact.map(e=>e.id))]={required,sufficient:cleared(mining),calls,guards:progress.map(p=>p.id),
      inRange,engaging,progress,mode,evading,workers:g.workers.map(a=>a.id),miningDeaths:mining.deadWorkers,assistDeaths:help?.deadWorkers};
  }
  return result;
}

function escapeMine(w,threats,mineralWalk) {
  const a=ownSnapshots[id(w)];
  const clearance=p=>Math.min(...threats.map(e=>dist(p,e)-e.range));
  const options=mines.filter(m=>mineAvailable(m)).map(m=>{
    const p=pos(m),length=Math.max(1,dist(a,p));
    const step={x:a.x+(p.x-a.x)*Math.min(1,3/length),y:a.y+(p.y-a.y)*Math.min(1,3/length)};
    return {m,p,length,gain:clearance(step)-clearance(a)};
  }).filter(o=>o.length>3 && o.gain>0.1 && clearance(o.p)>clearance(a)+2)
    .sort((l,r)=>Number(!safeBases.some(b=>b.mine && id(b.mine)===id(l.m)))-Number(!safeBases.some(b=>b.mine && id(b.mine)===id(r.m))) ||
      l.length-r.length || id(l.m)-id(r.m));
  for(const o of options){
    const p=reachableFrom(w,o.p.x,o.p.y);
    if(!p || dist(p,o.p)>4) continue;
    return o.m;
  }
  if(mineralWalk){
    const local=mines.filter(m=>mineAvailable(m) && dist(a,pos(m))<12 && dist(a,pos(m))>2)
      .sort((l,r)=>clearance(pos(r))-clearance(pos(l))||id(l)-id(r))[0];
    if(local) return local;
  }
  return null;
}

function evadeRaid(w,threats,mineralWalk) {
  const a=ownSnapshots[id(w)],mine=escapeMine(w,threats,mineralWalk);
  if(mine){
    order('Mine',[w],{unit:mine},2);
    const base=safeBases.find(b=>b.mine && id(b.mine)===id(mine));
    if(base){S.jobs[a.id]=base.id;S.jobMines[a.id]=id(mine);}
    else delete S.jobMines[a.id];
    return true;
  }
  const clearance=p=>Math.min(...threats.map(e=>dist(p,e)-e.range));
  const points=[[1,0],[-1,0],[0,1],[0,-1],[0.7,0.7],[-0.7,0.7],[0.7,-0.7],[-0.7,-0.7]]
    .map(([x,y])=>reachableFrom(w,a.x+10*x,a.y+10*y)).filter(p=>p && clearance(p)>clearance(a)+1)
    .sort((l,r)=>clearance(r)-clearance(l)||l.x-r.x||l.y-r.y);
  if(!points.length) return false;
  order('Move',[w],points[0],2);return true;
}

// One Castle, two Barracks. Keep this opening separate from the Archer/Catapult plan.
function runRaiderOpening() {
  const castles = done('Castle');
  const workerCount = workers.length + castles.filter(b => b.getRemainingBuildTime() >= 0).length;
  const houses = typed('House');
  const barracks = typed('Barracks');
  const {militia,workerDefense} = defendWorkers();
  directGuardArchers(militia);
  Object.assign(usedWorkers,militia);
  const mine = safeBases[0]?.mine;
  if (mine) {
    for (const w of workers) {
      if (!usedWorkers[id(w)] && !/^(Mine|Build |Repair)/.test(w.getCurrentOrderName() || ''))
        order('Mine', [w], {unit:mine}, 1);
    }
  }
  function produce(b, type) {
    const required = scope.getTypeFieldValue(type.toLowerCase(), 'supply');
    if (b.getRemainingBuildTime() >= 0) return;
    if (budget - reserved < cost(type) || supply + required > Math.min(capacity, cap)) {
      if(!productionBlock) productionBlock=type+' waiting: '+(budget-reserved<cost(type) ?
        Math.max(0,budget-reserved)+'/'+cost(type)+' spendable gold.' : 'insufficient free supply.');
      return;
    }
    purchases.push(type);
    scope.order('Train ' + type, [b]);
    budget -= cost(type);
    supply += required;
  }
  if (!houses.length || (capacity - supply <= 5 && capacity < cap &&
      barracks.length && houses.every(b => !b.isUnderConstruction()))) {
    ensure('House', houses.length + 1);
  }
  // Keep the initial economy growing, then fund both production buildings.
  if (workerCount < 10) for (const b of castles) produce(b, 'Worker');
  if (barracks.length < 2) ensure('Barracks', 2);
  if (!S.raiderTransition) {
    const evidence = enemyBuildings.find(b => b.getTypeName() === 'Barracks') ||
      enemyWrappers.find(u => (u.getEffectiveValue('isFlying') && u.getEffectiveValue('canAttackGround')) || u.getFieldValue('isMechanical') ||
        ['Soldier', 'Archer', 'Raider', 'Mage'].includes(u.getTypeName()));
    if (evidence) S.raiderTransition = {time: now, type: evidence.getTypeName()};
  }
  for (const b of done('Barracks')) produce(b, S.raiderTransition ? 'Archer' : 'Raider');
  if (S.raiderTransition) advanceTransitionArchers();
  if (workerCount >= 10 && workerCount < 12) for (const b of castles) produce(b, 'Worker');
  S.debug = {phase:S.raiderTransition ? 'two-Barracks Archers' : 'one-base Raiders', transition:S.raiderTransition, workers:workers.length, militia:Object.keys(militia).length, workerDefense, assetDefence:S.assetDefence, blocking, time:now};
  if (!own.some(u => u.getTypeName() === 'Raider') || S.raiderLoop) return;
  S.raiderLoop = true;
  function step() {
    const group = scope.getUnits({player:me, type:'Raider'}).sort(byId);
    if (!group.length) { S.raiderLoop = false; return; }
    const available=group.filter(u=>!S.guardTargets[id(u)]);
    if(available.length) runRaiderMicro(available);
    scope.setTimeout(step, 200);
  }
  step();
}

function raiderObjective(formation, start) {
  const sites = formation.castleSites || (formation.castleSites = {});
  for (const e of visible) {
    if (e.type === 'Castle') sites[e.id] = {x:e.x, y:e.y};
  }
  for (const key of Object.keys(sites)) {
    const p = sites[key];
    if (scope.canSeeField(p.x,p.y) && !visibleIDs[key]) {
      if (dist(p,start) <= 10) formation.mainCleared = true;
      delete sites[key];
    }
  }
  // A razed or abandoned start may be empty on our first visit.
  const reached = !formation.mainCleared && own.some(u =>
    u.getTypeName()==='Archer' && dist(pos(u),start)<6);
  if (reached && !Object.values(sites).some(p => dist(p,start)<=10) &&
      [[0,0],[-4,0],[4,0],[0,-4],[0,4]].every(([x,y])=>scope.canSeeField(start.x+x,start.y+y)))
    formation.mainCleared = true;
  if (!formation.mainCleared) return start;

  const from = formation.lastObjective || start;
  const nearest = list => list.sort((a,b) => dist(a,from)-dist(b,from) || a.x-b.x || a.y-b.y)[0];
  const castle = nearest(Object.values(sites));
  if (castle) return castle;
  const workers = visible.filter(e => e.type === 'Worker' && mines.some(m => dist(pos(m),e)<8));
  if (workers.length) return nearest(workers);
  const building = nearest(memory.filter(e => e.building));
  if (building) return building;

  // Search mines outside our base. Recheck the least recently visited sites after a sweep.
  const visited = formation.mineVisits || (formation.mineVisits = {});
  const candidates = mines.filter(m => dist(pos(m),home)>12 && dist(pos(m),start)>8);
  for (const m of candidates) if (scope.canSeeField(m.getX(),m.getY())) visited[id(m)] = now;
  const unseen = candidates.filter(m => !scope.canSeeField(m.getX(),m.getY()));
  const next = unseen.sort((a,b) => (visited[id(a)] || 0)-(visited[id(b)] || 0) ||
    dist(pos(a),from)-dist(pos(b),from) || id(a)-id(b))[0];
  return next ? pos(next) : start;
}

// Stage near home and release a compact group. A retreat remains in effect
// through loss of vision while reinforcements catch up.
function advanceTransitionArchers() {
  const formation = S.transitionFormation || (S.transitionFormation = {pushing:false});
  if (!enemyStarts.length && !formation.firstCastle) {
    const first = visible.find(e => e.type === 'Castle');
    if (first) formation.firstCastle = {x:first.x,y:first.y};
  }
  const start = enemyStarts[0] || formation.firstCastle;
  const front = start ? raiderObjective(formation,start) : visible[0] || formation.lastObjective || home;
  const distance = Math.max(1, dist(home, front));
  const rally = {x:home.x + 7*(front.x-home.x)/distance, y:home.y + 7*(front.y-home.y)/distance};
  formation.lastObjective = {x:front.x,y:front.y};
  const archers = army.filter(u => u.getTypeName() === 'Archer' && !assetGuards.has(id(u)));
  const spots = archers.map(pos);
  let center = rally, strength = 0;
  for (const point of spots) {
    const nearby = spots.filter(p => dist(p, point) <= 8).length;
    if (nearby > strength || (nearby === strength && dist(point, front) < dist(center, front))) {
      center = point;
      strength = nearby;
    }
  }
  const enemies = visible.filter(e => e.damage > 0 && e.type !== 'Worker');
  // Count a group at its point of contact, even when a scout sees it ahead of the Archers.
  let opposition = 0;
  for (const e of enemies) {
    if (dist(e, center) > 22 && dist(e, rally) > 18 && dist(e, front) > 18) continue;
    const count = enemies.filter(other => dist(e, other) <= 9).length;
    opposition = Math.max(opposition, count);
  }
  if (opposition && (opposition >= (formation.lastStrength || 0) || now >= formation.rememberUntil)) {
    formation.lastStrength = opposition;
    formation.rememberUntil = now + 90;
  }
  const expected = Math.max(opposition, now < formation.rememberUntil ? formation.lastStrength : 0);
  const raiderSupport = own.filter(u => u.getTypeName()==='Raider' &&
    u.getCurrentHP()>u.getEffectiveValue('hp')/2 && dist(pos(u),center)<=8).length;
  // A pair of healthy escorts can tip an even Archer fight. Never count distant reinforcements.
  const supportedStrength = strength + Math.floor(raiderSupport / 2);
  if (formation.pushing && (supportedStrength < expected || strength < 2)) formation.pushing = false;
  if (!formation.pushing && strength >= 4 && supportedStrength > expected) formation.pushing = true;
  const fallback = enemies.some(e => dist(e,rally) < 9) ? home : rally;
  formation.anchor = formation.pushing ? center : fallback;
  const homeThreat = enemies.find(e => dist(e, home) < 14);
  const fighters = enemyWrappers.filter(e => e.getTypeName() !== 'Worker' && e.getEffectiveValue('dmg') > 0);
  const opportunities = fighters.filter(e => dist(pos(e),center) <= 15);
  const contact = opportunities.slice().sort((a,b) => dist(pos(a),center) - dist(pos(b),center))[0];
  // Follow only Workers with combat orders. Mining Workers are never a retreat trigger.
  const pulled = enemyWrappers.filter(e => e.getTypeName()==='Worker' &&
    ['Attack','AMove'].includes(e.getCurrentOrderName()) && dist(pos(e),center)<=12);
  const previousScreen = formation.workerScreen;
  formation.workerScreen = null;
  if (formation.pushing && pulled.length >= (previousScreen ? 1 : 3) && dist(center,home)>16) {
    const nearest = pulled.slice().sort((a,b)=>dist(pos(a),center)-dist(pos(b),center))[0];
    const length = Math.max(1,dist(center,home));
    const back = previousScreen?.back || {x:center.x+5*(home.x-center.x)/length,y:center.y+5*(home.y-center.y)/length};
    formation.workerScreen = {back,worker:id(nearest)};
  }
  const siege = opportunities.filter(e=>e.getTypeName()==='Catapult' &&
    strength >= 5 && strength >= 2*opportunities.filter(g=>g.getTypeName()!=='Catapult' &&
      dist(pos(g),pos(e))<=8).length+2).sort((a,b)=>dist(pos(a),center)-dist(pos(b),center))[0];
  formation.exposedSiege = siege && !homeThreat ? id(siege) : null;
  if (siege && !homeThreat) {
    formation.pushing = true;
    formation.anchor = center;
  }
  const goal = homeThreat || (contact && pos(contact)) || front;
  // Prefer the target that the most bows can already reach. Within that group,
  // finish wounded units and allocate excess arrows to the next available enemy.
  const targets = opportunities.map(e => {
    const point = pos(e);
    return {unit:e, point, hp:e.getCurrentHP(), shooters:spots.filter(p => dist(p,point) <= 8).length};
  }).sort((a,b) => b.shooters-a.shooters || a.hp-b.hp || dist(a.point,center)-dist(b.point,center) ||
    id(a.unit)-id(b.unit));
  formation.focus = targets[0] && id(targets[0].unit);
  // Muster a local strike squad when bows can cover a melee approach. Keep its
  // membership and objective for one volley, including the Raider windup.
  const tick = Math.round(now*20);
  const wing = own.filter(u => u.getTypeName()==='Raider' && dist(pos(u),center)<=10);
  const bows = archers.filter(a => dist(pos(a),center)<=8);
  // While approaching, sort each rank across the direction of travel so
  // neighbours do not have to cross one another to reach their places.
  formation.raiderSlots = {};
  const bowSlots = {};
  const closestEnemy = opportunities.reduce((d,e)=>Math.min(d,dist(pos(e),center)),Infinity);
  const frontInContact = wing.some(u => fighters.some(e => dist(pos(u),pos(e))<4.5));
  const onApproach = closestEnemy>7.5 && (closestEnemy<20 || dist(center,front)<38);
  if (formation.pushing && wing.length && bows.length>=3 && !frontInContact && onApproach) {
    const origin = bows.reduce((q,a)=>({x:q.x+a.getX()/bows.length,y:q.y+a.getY()/bows.length}),{x:0,y:0});
    const heading = contact ? pos(contact) : goal, length = Math.max(1,dist(origin,heading));
    const dx=(heading.x-origin.x)/length, dy=(heading.y-origin.y)/length;
    const depth = u => (u.getX()-origin.x)*dx + (u.getY()-origin.y)*dy;
    const lateral = u => -u.getX()*dy + u.getY()*dx;
    const leading = wing.filter(u=>depth(u)>1.6).length >= Math.ceil(wing.length/2);
    const assignRank = (members,slots,forwardDistance,spacing) => {
      members.slice().sort((a,b)=>lateral(a)-lateral(b)||id(a)-id(b)).forEach((u,i)=>{
        const offset = Math.max(-5,Math.min(5,(i-(members.length-1)/2)*spacing));
        const ahead = forwardDistance + 0.15*Math.abs(offset);
        const q=reachableFrom(u,origin.x+dx*ahead-dy*offset,origin.y+dy*ahead+dx*offset);
        if (q) slots[id(u)]=q;
      });
    };
    if (!formation.deployedAt || now-formation.deployedAt>22) formation.deployedAt=now;
    const forming = now-formation.deployedAt<3 && !leading;
    assignRank(wing,formation.raiderSlots,forming ? 3.3 : 5.4,1.4);
    // Release the bows after three seconds even if terrain breaks the formation.
    if (forming) assignRank(bows,bowSlots,-1.5,1.4);
  } else if (!formation.pushing) {
    formation.deployedAt=0;
  }
  let squad = formation.strikeSquad;
  if (squad && (!formation.pushing || tick>squad.until || !targets.some(t=>id(t.unit)===squad.target))) {
    formation.strikeSquad = squad = null;
  }
  if (!squad && formation.pushing && bows.length>=3 && tick >= (formation.nextStrike || 0)) {
    for (const t of targets) {
      const members = wing.filter(u => u.getCurrentHP()>20 && dist(pos(u),t.point)<=8 &&
        u.getValue('tickOfLastWeaponFired')+u.getEffectiveValue('weaponCooldown')<=tick+20);
      const cover = bows.filter(a => dist(pos(a),t.point)<=a.getEffectiveValue('range')+3);
      if (!members.length || cover.length<3) continue;
      squad = {start:tick, until:tick+52, target:id(t.unit), raiders:members.map(id), archers:cover.map(id)};
      formation.strikeSquad = squad;
      formation.nextStrike = tick+55;
      break;
    }
  }
  for (let i=0; i<archers.length; i++) {
    const u = archers[i], p = spots[i];
    const localFoes = enemies.filter(e => dist(e,p) <= 12).length;
    const closeFriends = spots.filter(q => dist(q,p) <= 8).length;
    const unsupported = localFoes > closeFriends + (dist(p,center)<=5 ? Math.floor(raiderSupport/2) : 0);
    if (siege && !homeThreat && (!formation.workerScreen || dist(p,pos(siege))<=u.getEffectiveValue('range')+1) && dist(p,center)<=10) {
      if (u.getCurrentOrderName()!=='Attack' || u.getValue('targetUnit')?.id!==id(siege))
        order('Attack',[u],{unit:siege},1);
      continue;
    }
    if (formation.workerScreen && dist(p,center)<=9) {
      const chaser = pulled.slice().sort((a,b)=>dist(p,pos(a))-dist(p,pos(b)))[0];
      const gap = dist(p,pos(chaser));
      const ready = u.getValue('tickOfLastWeaponFired')+u.getEffectiveValue('weaponCooldown')<=tick;
      if (gap>3 && gap<=u.getEffectiveValue('range') && ready) {
        if (u.getCurrentOrderName()!=='Attack' || u.getValue('targetUnit')?.id!==id(chaser))
          order('Attack',[u],{unit:chaser},1);
      } else {
        // Preserve spacing while stepping back, especially inside Catapult range.
        const back=formation.workerScreen.back;
        const length = Math.max(1,dist(center,home));
        const dx=(home.x-center.x)/length, dy=(home.y-center.y)/length;
        const step=Math.min(4, (back.x-p.x)*dx+(back.y-p.y)*dy);
        if (gap<8 && step>0.8) move(u,{x:p.x+step*dx,y:p.y+step*dy},'Move');
        else if (gap<=u.getEffectiveValue('range') && u.getCurrentOrderName()!=='Attack') order('Attack',[u],{unit:chaser},1);
        else if (gap>u.getEffectiveValue('range') && u.getCurrentOrderName()!=='Hold Position') order('Hold Position',[u],null,1);
      }
      continue;
    }
    if (!formation.pushing || unsupported) {
      if (dist(p,fallback) > 4) move(u,fallback,'Move');
      else if (u.getCurrentOrderName() !== 'Hold Position') order('Hold Position',[u],null,2);
    } else if (bowSlots[id(u)]) {
      const slot=bowSlots[id(u)];
      if (dist(p,slot)>1.2) order('Move',[u],slot,1);
      else if (u.getCurrentOrderName()!=='Hold Position') order('Hold Position',[u],null,1);
    } else if (dist(p,center) > 8) {
      move(u,center,'Move');
    } else {
      const reach = u.getEffectiveValue('range') + 2;
      const shared = squad && squad.archers.includes(id(u)) && targets.find(t => id(t.unit)===squad.target &&
        t.hp>0 && dist(p,t.point)<=reach);
      const target = shared || targets.find(t => t.hp>0 && dist(p,t.point)<=reach);
      if (target) {
        if (u.getValue('targetUnit')?.id !== id(target.unit) || u.getCurrentOrderName() !== 'Attack')
          order('Attack',[u],{unit:target.unit},1);
        target.hp -= Math.max(1,u.getEffectiveValue('dmg')-target.unit.getEffectiveValue('armor'));
      } else if (contact || u.getCurrentOrderName() !== 'Attack') move(u,goal,'AMove');
    }
  }
}

function runRaiderMicro(group) {
  const tick = Math.round(scope.getCurrentGameTimeInSec() * 20);
  const seen = u => !u.isNeutral() && scope.canSeeField(u.getX(), u.getY());
  const enemies = scope.getUnits({enemyOf:me}).filter(u => seen(u) && !u.getFieldValue('isFlying'));
  const structures = scope.getBuildings({enemyOf:me}).filter(seen);
  const positions = group.map(pos);
  // Dress the approaching line across the path to contact. A Raider already in
  // striking distance keeps its windup, and distant reinforcements keep moving.
  const front = enemyStarts[0];
  const forwardLength = front && dist(front,home);
  const side = forwardLength ? {x:-(front.y-home.y)/forwardLength,
    y:(front.x-home.x)/forwardLength} : {x:0,y:1};
  // A healthy Raider may pass one ranged screen on its way to the main mine.
  // New runs can start in the first seven minutes and last at most 14 seconds.
  const raidDeadline = 7 * 60 * 20, passDuration = 14 * 20;
  const canPass = !S.raiderTransition && front && tick < raidDeadline + passDuration;
  if (!canPass) delete S.raiderPass;
  const passUntil = canPass && (S.raiderPass || (S.raiderPass = {}));
  const frontMine = canPass && mines.reduce((best, mine) =>
    !best || dist(pos(mine), front) < dist(pos(best), front) ? mine : best, null);
  const mineralLine = frontMine ? pos(frontMine) : front;
  const lateral = p => p.x*side.x+p.y*side.y;
  const nearest = (list, point, score) => {
    let best, bestScore = Infinity;
    for (const u of list) {
      const s = score(u, dist(pos(u), point));
      if (s < bestScore) { best = u; bestScore = s; }
    }
    return best;
  };
  const orders = S.raiderOrders || (S.raiderOrders = {});
  const observations = S.raiderPositions || {};
  S.raiderPositions = {};
  for (const e of enemies) S.raiderPositions[id(e)] = pos(e);
  const committed = new Map();
  const readyInTicks = u => u.getValue('tickOfLastWeaponFired') + u.getEffectiveValue('weaponCooldown') - tick;
  const readyFriends = group.filter(friend => readyInTicks(friend) <= 12);
  function damagePerHit(u,e) {
    const tags = u.getFieldValue('dmgModifierAttributes') || [];
    const bonus = u.getFieldValue('dmgModifierAddition') || [];
    let damage = u.getEffectiveValue('dmg');
    for (let i=0;i<tags.length;i++) if (e.getFieldValue(tags[i])) damage += bonus[i] || 0;
    return Math.max(1,damage-e.getEffectiveValue('armor'));
  }
  const threats = enemies.filter(e => e.getTypeName() !== 'Worker' || e.getCurrentOrderName() === 'Attack');
  // Compare the first second of two approaches. A ready enemy contributes its
  // damage if it can close on the Raider during that approach.
  function exposure(start, destination) {
    const distance = dist(start,destination);
    const fraction = distance ? Math.min(1, 3.2/distance) : 0;
    const end = {x:start.x+(destination.x-start.x)*fraction, y:start.y+(destination.y-start.y)*fraction};
    let damage = 0;
    for (const e of threats) {
      if (e.getValue('tickOfLastWeaponFired') + e.getEffectiveValue('weaponCooldown') > tick+20) continue;
      const reach = 1 + e.getEffectiveValue('range') + 20*e.getEffectiveValue('movementSpeed');
      if (dist(pos(e),end) <= reach) damage += e.getEffectiveValue('dmg');
    }
    return damage;
  }
  const coveringBows = S.transitionFormation?.pushing ? scope.getUnits({player:me,type:'Archer'}) : [];
  for (const u of group) {
    const p = pos(u);
    let target = nearest(enemies, p, (e,d) => d);
    let contact = target && dist(p,pos(target));
    const previous = orders[id(u)];
    function issue(name, dest, key) {
      if (previous && previous.key === key && tick - previous.tick < 30) return;
      scope.order(name,[u],dest);
      orders[id(u)] = {key,tick};
    }
    const threat = nearest(threats, p, (e,d) => d);
    const t = threat && pos(threat), gap = t && dist(p,t);
    const readyIn = readyInTicks(u);
    const formation = S.transitionFormation;
    if (S.raiderTransition && formation?.anchor) {
      const anchor = formation.anchor;
      const lastHit = u.getLastAttack();
      const underFire = lastHit && tick - lastHit.time*20 < 40 ||
        threats.some(e => e.getValue('targetUnit')?.id === id(u) &&
          dist(p,pos(e)) <= e.getEffectiveValue('range')+2);
      const engine = threats.find(e=>id(e)===formation.exposedSiege);
      if (engine && dist(p,pos(engine))<=9 && coveringBows.filter(a=>dist(pos(a),pos(engine))<=10).length>=3 &&
          u.getCurrentHP()>20 && readyIn<=10) {
        issue('Attack',{unit:engine},'siege:'+id(engine));
        continue;
      }
      if (formation.workerScreen && dist(p,anchor)<=12) {
        const chaser = threats.find(e=>id(e)===formation.workerScreen.worker);
        if (chaser && readyIn<=0 && dist(p,pos(chaser))<2 && !underFire)
          issue('Attack',{unit:chaser},'retreat-hit:'+id(chaser));
        else {
          const back = formation.workerScreen.back;
          const dest = reachableFrom(u,back.x,back.y);
          if (dest) issue('Move',dest,'worker-pull:'+Math.round(dest.x)+','+Math.round(dest.y));
        }
        continue;
      }
      const slot = formation.raiderSlots?.[id(u)];
      if (slot && (!threat || gap>4.5) && !underFire) {
        if (dist(p,slot)>0.9) issue('Move',slot,'rank:'+Math.round(slot.x)+','+Math.round(slot.y));
        else issue('Hold Position',null,'front-rank');
        continue;
      }
      const squad = formation.strikeSquad;
      if (squad && formation.pushing && tick<=squad.until && squad.raiders.includes(id(u)) &&
          u.getValue('tickOfLastWeaponFired') < squad.start) {
        const mark = threats.find(e=>id(e)===squad.target);
        if (mark && dist(p,pos(mark))<=8 && dist(anchor,pos(mark))<=10) {
          const volley = threats.reduce((total,e) => e.getValue('targetUnit')?.id===id(u) &&
            dist(pos(e),p)<=e.getEffectiveValue('range')+2 ? total+e.getEffectiveValue('dmg') : total,0);
          if (u.getCurrentHP()>Math.max(12,volley*(dist(p,pos(mark))<3 ? 0.45 : 0.85))) {
            issue('Attack',{unit:mark},'escort-hit:'+id(mark));
            continue;
          }
        }
      }
      // The front rank may reach a target just before the named squad forms.
      // Take a ready, covered hit in its own lane instead of passing through the bows.
      const laneTarget = nearest(threats.filter(e=> e.getTypeName()!=='Worker' &&
        dist(p,pos(e))<5 && coveringBows.filter(a=>dist(pos(a),pos(e))<=8.5).length>=3),p,(e,d)=>d);
      if (laneTarget && readyIn<=8 && u.getCurrentHP()>25 &&
          (!underFire || dist(p,pos(laneTarget))<3.5)) {
        issue('Attack',{unit:laneTarget},'lane-hit:'+id(laneTarget));
        continue;
      }
      const supported = formation.pushing && dist(p,anchor) <= 9;
      const reachableTargets = supported && !underFire && readyIn <= 4
        ? threats.filter(e => dist(p,pos(e)) <= 7 && dist(anchor,pos(e)) <= 9) : [];
      const strike = reachableTargets.find(e => id(e) === formation.focus) ||
        nearest(reachableTargets,p,(e,d) => d);
      if (strike) {
        issue('Attack',{unit:strike},'escort-hit:'+id(strike));
      } else {
        let back = anchor;
        if (formation.pushing && underFire && threat) {
          const t = pos(threat), length = Math.max(1,dist(t,anchor));
          back = {x:anchor.x+3*(anchor.x-t.x)/length, y:anchor.y+3*(anchor.y-t.y)/length};
        }
        const dest = reachableFrom(u,back.x,back.y);
        if (dest && dist(p,back)>1.5)
          issue('Move',dest,'escort:'+Math.round(dest.x)+','+Math.round(dest.y));
        else issue('Hold Position',null,'escort-hold');
      }
      continue;
    }
    if (canPass) {
      const raiderID = id(u), hp = u.getCurrentHP();
      const distanceToMain = dist(p, front);
      if (!passUntil[raiderID] && tick < raidDeadline && hp > 90 && dist(p, home) > 18 &&
          distanceToMain > 15 && distanceToMain < 45 &&
          threats.some(e => e.getEffectiveValue('range') >= 3 && dist(pos(e), p) < 11)) {
        passUntil[raiderID] = tick + passDuration;
      }
      if (passUntil[raiderID] > tick && hp > 65 && dist(p, mineralLine) > 7) {
        const dest = reachableFrom(u, mineralLine.x, mineralLine.y);
        if (dest) {
          issue('Move', dest, 'pass-screen');
          continue;
        }
      }
    }
    const old = threat && observations[id(threat)];
    const fleeing = old && (t.x-old.x)*(t.x-p.x)+(t.y-old.y)*(t.y-p.y) > 0.12;
    if (threat && gap < 6 && !fleeing && readyIn > Math.max(7, gap*4)) {
      // Adjacent Raiders take slightly different escape lanes before turning back.
      let dx = (p.x-t.x)/Math.max(0.1,gap), dy = (p.y-t.y)/Math.max(0.1,gap);
      for (const q of positions) {
        const d = dist(q,p);
        if (d > 0 && d < 1.8) { dx += 0.45*(p.x-q.x)/d; dy += 0.45*(p.y-q.y)/d; }
      }
      const angle = Math.atan2(dy,dx);
      let escape, bestClearance = -Infinity;
      const nearby = threats.filter(e => dist(p,pos(e)) < 7);
      for (const offset of [0,0.65,-0.65,1.25,-1.25]) {
        const dest = {x:p.x+3.3*Math.cos(angle+offset),y:p.y+3.3*Math.sin(angle+offset)};
        if (!scope.positionIsPathable(Math.ceil(dest.x),Math.ceil(dest.y)) ||
            !scope.isReachable(Math.ceil(p.x),Math.ceil(p.y),Math.ceil(dest.x),Math.ceil(dest.y))) continue;
        const clearance = Math.min(...nearby.map(e=>dist(dest,pos(e))-e.getEffectiveValue('range')));
        if (clearance > bestClearance+0.3) { bestClearance=clearance; escape=dest; }
      }
      if (escape) {
        const dest=escape;
        const flash = gap < 2 && u.getCurrentHP() < 95 && u.getMana() >= 25 && scope.canSeeField(dest.x,dest.y);
        issue(flash?'Flash':'Move', dest, 'away:'+Math.round(dest.x)+','+Math.round(dest.y));
      }
    } else if (target && contact < 13) {
      // Retreat has already taken priority. Never lengthen a melee windup or
      // expose the attacker to more damage to finish a wounded target.
      const baseRisk = exposure(p,pos(target));
      let focus = null, bestRisk = baseRisk, bestScore = Infinity;

      if (contact > 1.2 && readyIn <= 12) {
        for (const e of enemies) {
          const q = pos(e), distance = dist(p,q);
          if (distance > 5) continue;
          const risk = exposure(p,q);
          if (risk > baseRisk || (risk > 0 && distance > contact+0.8)) continue;
          const remaining = e.getCurrentHP()-(committed.get(id(e)) || 0);
          const hit = damagePerHit(u,e);
          const helpers = readyFriends.filter(friend => dist(pos(friend),q)<=distance+0.8 && dist(pos(friend),q)<5);
          if (remaining <= 0 || remaining > hit*helpers.length) continue;
          const score = remaining/hit + distance*0.3;
          if (risk < bestRisk || (risk === bestRisk && score < bestScore)) {
            bestRisk=risk; bestScore=score; focus=e;
          }
        }
      }
      if (focus) { target=focus; contact=dist(p,pos(target)); }
      const neighbours = !focus && contact > 4 && contact < 10
        ? positions.filter(q => dist(q,p) < 4).sort((a,b) => lateral(a)-lateral(b)) : [];
      const rank = neighbours.findIndex(q => q.x === p.x && q.y === p.y);
      const offset = Math.max(-2.5, Math.min(2.5, (rank-(neighbours.length-1)/2)*1.15));
      const dest = {x:target.getX()+side.x*offset,y:target.getY()+side.y*offset};
      if (neighbours.length >= 3 && Math.abs(offset)>0.6 && exposure(p,dest)<=baseRisk && scope.positionIsPathable(Math.ceil(dest.x),Math.ceil(dest.y))) {
        issue('Move',dest,'flank:'+Math.round(dest.x)+','+Math.round(dest.y));
      } else {
        issue('Attack',{unit:target},'attack:'+id(target));
        if (readyIn <= 12 && contact < 5) {
          const hit = damagePerHit(u,target);
          committed.set(id(target),(committed.get(id(target)) || 0)+hit);
        }
      }
    } else {
      const building = nearest(structures,p,(b,d) => d);
      if (building) issue('Attack',{unit:building},'attack:'+id(building));
      else {
        const objective = target ? pos(target) : enemyStarts[0];
        if (objective) issue('AMove',objective,'advance:'+Math.round(objective.x)+','+Math.round(objective.y));
      }
    }
  }
  const living = new Set(group.map(u=>String(id(u))));
  for (const key of Object.keys(orders)) if (!living.has(key)) delete orders[key];
}

function sevenHandleChat(messages, objective, makeReports) {
  const prefix = 'Venibot P' + me + ' ';
  const announce = () => scope.chatMsg(prefix + 'commander objective set to ' + objective);
  if (S.chatDebug && S.chatObjective !== objective) announce();
  S.chatObjective = objective;
  let reports;
  for (const {text} of messages) {
    const command = text.trim().toLowerCase();
    if (command === 'venibot debug') {
      S.chatDebug = !S.chatDebug;
      scope.chatMsg('Venibot commander debug ' + (S.chatDebug ? 'on' : 'off'));
      if (S.chatDebug) announce();
    } else {
      const match = /^venibot (why|mines|army|spending)$/.exec(command);
      if (!match) continue;
      if (!reports) reports = makeReports();
      for (const line of reports[match[1]]) scope.chatMsg(prefix + match[1] + ': ' + line);
    }
  }
}

function sevenMineReport(minerCounts, goal) {
  const lines=[];
  const seen=new Set();
  for(const base of bases) {
    const mine=base.mine || safeBases.find(b=>b.id===base.id)?.mine ||
      mines.find(m=>dist(base,pos(m))<14 && S.surveyedMines[id(m)]?.gold===0);
    if(!mine || seen.has(id(mine))) continue;
    seen.add(id(mine));
    const gold=S.surveyedMines[id(mine)]?.gold;
    const miners=minerCounts[id(mine)] || 0;
    lines.push('Mine '+mine.getX()+', '+mine.getY()+' — '+(gold===undefined?'gold unknown':gold+' gold')+
      ', '+miners+' assigned miners'+(base.finished?'':' (Castle under construction)'));
  }
  if(!lines.length) lines.push('No active mining line.');
  if(S.pending.Castle) lines.push('Castle ordered at '+S.pending.Castle.x+', '+S.pending.Castle.y+'.');
  else if(goal && !bases.some(b=>!b.finished))
    lines.push('Seeking a mining base. '+healthyMines.size+'/'+miningGoal+' productive mines.');
  return lines;
}

function sevenSpendingReport(priority) {
  const lines=[scope.getGold()+' gold. '+Math.max(0,budget-reserved)+' spendable after orders and reservations.'];
  if(purchases.length) lines.push('Ordered this update: '+purchases.join(', ')+'.');
  if(blocking) lines.push('Build plan: '+blocking+'.');
  if(productionBlock) lines.push(productionBlock);
  else if(!purchases.length) {
    const queues=buildings.filter(b=>!b.isUnderConstruction()).map(b=>b.getUnitTypeNameInProductionQueAt(1)).filter(Boolean);
    if(queues.length) lines.push('In production: '+queues.join(', ')+'.');
    lines.push('Priority order: '+priority.join(' > ')+'.');
  }
  return lines;
}

function sevenCommanderReports() {
  const wave=S.commander;
  let why;
  if(wave.objective==='grow') why='Assign '+missingMiners+' more '+(missingMiners===1?'miner':'miners')+' to reach '+C.workersPerMine+' per mine.';
  else if(wave.objective==='expand') why=S.pending.Castle?'Castle builder en route.':'Survey the next mine and reserve '+cost('Castle')+' gold for its Castle.';
  else if(wave.objective==='attack') why=wave.reason+'. Wave has '+combatSupply+' combat supply. Regroup below '+Math.ceil(wave.peak*C.commander.retreatFraction)+'.';
  else if(wave.reason==='opening') why=done('Castle').length+'/'+C.commander.firstAttackCastles+' finished Castles for the first push.';
  else if(S.firstAttackAt===undefined) why=combatSupply+'/'+C.commander.launchSupply+' live combat supply for the first push.';
  else why=(combatSupply+workers.length*scope.getTypeFieldValue('worker','supply'))+'/'+(cap-C.commander.relaunchHeadroom)+' live supply to launch again.';
  const groups={};
  for(const role of Object.values(S.assignment)) {
    const label=role.startsWith('defend:')?'defending':role;
    groups[label]=(groups[label] || 0)+1;
  }
  const roles=Object.entries(groups).map(([label,n])=>n+' '+label);
  if(army.some(u=>id(u)===S.scoutId)) roles.push('1 scouting');
  const orders=roles.length?[roles.join(', ')+'.']:['No combat units.'];
  if(mainMembers.length) {
    const at=main.objective;
    if(main.state==='gather') orders.push('Gathering at '+Math.round(rally.x)+', '+Math.round(rally.y)+'. '+
      Math.round(gather*mainMembers.length)+'/'+mainMembers.length+' at rally. Launch requires '+Math.ceil(C.gatherFraction*mainMembers.length)+' gathered.');
    else orders.push('Main squad: '+main.state+' toward '+Math.round(at.x)+', '+Math.round(at.y)+'.');
  }
  return {why:[wave.objective+' — '+why], mines:sevenMineReport(assigned,needMiningBase),
    army:orders, spending:sevenSpendingReport(C.commander.priority[objective])};
}

function sevenRaiderReports() {
  const mine=safeBases[0]?.mine;
  const miners=workers.filter(u=>u.getCurrentOrderName()==='Mine').length;
  const raiders=own.filter(u=>u.getTypeName()==='Raider');
  const orders={};
  for(const u of raiders) {
    const action=u.getCurrentOrderName() || 'idle';
    orders[action]=(orders[action] || 0)+1;
  }
  const unit=S.raiderTransition?'Archer':'Raider';
  const archerCount=own.filter(u=>u.getTypeName()==='Archer').length;
  return {why:['Raiders — one-base opening. '+(S.raiderTransition?'Producing Archers after seeing '+S.raiderTransition.type+'. ':'')+workers.length+'/12 Workers, '+done('Barracks').length+'/2 finished Barracks.'],
    mines:sevenMineReport(mine?{[id(mine)]:miners}:{},false),
    army:[raiders.length+' Raiders. '+(S.raiderTransition?archerCount+' Archers. ':'')+Object.entries(orders).map(([action,n])=>n+' '+action).join(', ')],
    spending:sevenSpendingReport(workers.length<10?['Worker','Barracks',unit]:['Barracks',unit,'Worker'])};
}

if (!scope.seven) {
  scope.seven = {
    config: SEVEN_CONFIG, model: createSevenPredictor(), phase: 0, phaseHistory: [],
    memory: {}, pending: {}, investments: {}, jobs: {}, jobMines: {}, repairs: {}, orders: {}, squads: {},
    assignment: {}, raids: {}, nextScout: SEVEN_CONFIG.scoutStart, scoutIndex: 0, lastDebug: -99,
    spotTry: 0, maxed: false, launched: false, predictions: {}, nextPrediction: {},
    stats: {lostBuildings: 0, failedBuilds: 0, recoveredBuilds: 0, predictionCalls: 0}
  };
}
var S = scope.seven, C = S.config, P = S.model;
var now = scope.getCurrentGameTimeInSec(), me = scope.getMyPlayerNumber();
var id = u => u.getUnitID();
var byId = (a,b) => id(a)-id(b);
var pos = u => ({x: u.getX(), y: u.getY()});
// Field(px,py,true) uses ceil. The Scope grid APIs truncate their arguments.
function reachableFrom(u,x,y) {
  return scope.getClosestReachableField(Math.ceil(u.getX()),Math.ceil(u.getY()),x,y);
}
function mineSurveyTile(scout,point,mine) {
  const height=scope.getHeightLevel(mine.x,mine.y);
  const fromX=Math.ceil(scout.getX()),fromY=Math.ceil(scout.getY());
  const x=Math.round(point.x),y=Math.round(point.y);
  let best=null,bestDistance=Infinity;
  for(let dx=-4;dx<=4;dx++) for(let dy=-4;dy<=4;dy++) {
    const tx=x+dx,ty=y+dy,distance=(tx-point.x)**2+(ty-point.y)**2;
    if(distance>=bestDistance || tx<1 || ty<1 || tx>=scope.getMapWidth() || ty>=scope.getMapHeight()) continue;
    if(scope.getHeightLevel(tx,ty)!==height || !scope.positionIsPathable(tx,ty) || !scope.isReachable(fromX,fromY,tx,ty)) continue;
    best={x:tx,y:ty}; bestDistance=distance;
  }
  return best;
}
function onWalkableField(u) {
  return scope.positionIsPathable(Math.ceil(u.getX()),Math.ceil(u.getY()));
}
var dist = P.distance;
var own = scope.getUnits({player: me}).sort(byId);
var buildings = scope.getBuildings({player: me}).sort(byId);
var workers = own.filter(u => u.getTypeName() === 'Worker');
var army = own.filter(u => ['Archer','Catapult'].includes(u.getTypeName()));
var byID = {};
own.concat(buildings).forEach(u => { byID[id(u)] = u; });
var typed = type => buildings.filter(b => b.getTypeName() === type);
var done = type => typed(type).filter(b => !b.isUnderConstruction());
var start = S.start || scope.getStartLocationForPlayerNumber(me) || (buildings[0] && pos(buildings[0]));
if (!start) return;
S.start = {...start};
var home = done('Castle')[0] ? pos(done('Castle')[0]) : start;
var cost = type => scope.getTypeFieldValue(type.toLowerCase(), 'cost') || 0;
const purchases=[];
let productionBlock='';
var budget = scope.getGold(), reserved = 0, blocking = '', usedWorkers = {};
var supply = scope.getCurrentSupply(), capacity = scope.getMaxSupply();
// Own player state only. getMaxSupply() is housing capacity, NOT the game's supply cap.
var cap = scope.player.supplyCap;
if (supply >= cap) S.maxed = true;

// World/memory: wrappers exist only for this update. Buildings require CURRENT vision,
// since getBuildings() alone also returns previously seen buildings under fog.
var enemyWrappers = scope.getUnits({enemyOf: me}).filter(u => !u.isNeutral() && scope.canSeeField(u.getX(), u.getY())).sort(byId);
var enemyBuildings = scope.getBuildings({enemyOf: me}).filter(u => !u.isNeutral() && scope.canSeeField(u.getX(), u.getY())).sort(byId);
var visible = enemyWrappers.concat(enemyBuildings).map(u => P.snapshot(u, now));
var visibleIDs = {};
visible.forEach(u => { visibleIDs[u.id] = true; S.memory[u.id] = {...u, uncertainty: 0}; });
Object.keys(S.memory).forEach(key => {
  const m = S.memory[key], age = now-m.seen;
  if (!visibleIDs[key] && ((scope.canSeeField(m.x,m.y) && m.building) || age > (m.building ? C.buildingMemorySeconds : C.memorySeconds))) delete S.memory[key];
  else {
    m.uncertainty = age * m.speed;
    if(!visibleIDs[key] && scope.canSeeField(m.x,m.y)) m.lastPositionCleared=true;
  }
});
var memory = Object.values(S.memory).sort((a,b) => a.id-b.id);
var observations = own.concat(buildings.filter(b => !b.isUnderConstruction())).map(u => P.snapshot(u, now));
var ownSnapshots = {};
observations.forEach(u => { ownSnapshots[u.id] = u; });
var mines = scope.getBuildings({type: 'Goldmine'}).sort(byId);
S.unsafeMines=S.unsafeMines||{};
S.surveyedMines=S.surveyedMines||{};
for(const m of mines) if(scope.canSeeField(m.getX(),m.getY())) {
  const gold=m.getValue('gold');
  S.surveyedMines[id(m)]={time:now,available:gold>0,gold};
}
const surveySafe=m=>!(S.unsafeMines[m.getX()+','+m.getY()]>now);
// Neutral mines' positions are public map information; depletion is read only in vision.
var mineAvailable = m => S.surveyedMines[id(m)]?.available!==false;
var observedPower=e=>P.power(e)*(e.lastPositionCleared?0.15:1)*Math.max(0.25,1-(now-e.seen)/C.memorySeconds);
var bases = typed('Castle').map(b => {
  const p = pos(b);
  const mine = mines.filter(m => mineAvailable(m) && dist(pos(m),p) < 14).sort((a,b) => dist(pos(a),p)-dist(pos(b),p) || id(a)-id(b))[0];
  const threats = memory.filter(e => e.damage > 0 && dist(e,p) < C.threatRadius + Math.min(8,e.uncertainty));
  const threat = threats.reduce((sum,e) => sum+observedPower(e),0);
  const support = observations.filter(u => u.building && u.damage > 0 && dist(u,p)<14).reduce((sum,u) => sum+P.power(u),0);
  return {id: id(b), ...p, mine, finished: !b.isUnderConstruction(), threat, support, threats, workers: 0};
});
var totalPower = army.reduce((v,u) => v + P.power(ownSnapshots[id(u)]),0);
// Overlapping Castle radii often see the same raid. Allocate a defender budget for it once.
const nearestThreatBase={};
for(const b of bases) {
  b.defenseDemand=0;
  for(const e of b.threats) {
    const previous=nearestThreatBase[e.id];
    if(!previous||dist(b,e)<dist(previous,e)||(dist(b,e)===dist(previous,e)&&b.id<previous.id)) nearestThreatBase[e.id]=b;
  }
}
for(const e of memory) {
  const b=nearestThreatBase[e.id];
  if(b) b.defenseDemand+=observedPower(e);
}
var emergency = bases.some(b => b.threat > Math.max(50,totalPower+b.support)*C.emergencyRatio);
var safeBases = bases.filter(b => b.finished && b.mine && b.threat < Math.max(70,totalPower+b.support));
if (!safeBases.length) safeBases = bases.filter(b => b.finished && b.mine);
// A surviving Castle can receive deliveries from a distant mine after its own runs dry.
if(!safeBases.length) {
  for(const b of bases.filter(b=>b.finished)) {
    const options=mines.filter(m=>mineAvailable(m) && surveySafe(m) &&
      !memory.some(e=>(e.building||e.damage>0)&&dist(e,pos(m))<14))
      .sort((a,c)=>dist(pos(a),b)-dist(pos(c),b)||id(a)-id(c));
    const worker=workers.find(onWalkableField);
    if(!worker) continue;
    const mine=options.slice(0,6).find(m=>{
      const edge=reachableFrom(worker,m.getX(),m.getY());
      return edge && dist(edge,pos(m))<4;
    });
    if(mine) safeBases.push({...b,mine,remote:true});
  }
}

// Keep the scripted opening until the third Castle is established. Foundations
// count as future mines, and several Castles sharing one mine count only once.
const postOpening=S.phase>=4 || done('Castle').length>=3;
const miningGoal=S.firstAttackAt===undefined ? C.expansion.miningBasesBeforeAttack : C.expansion.miningBasesAfterAttack;
const lowMine=m=>S.surveyedMines[id(m)]?.gold<C.expansion.lowMineGold;
const healthyMines=new Set(bases.filter(b=>b.mine && !lowMine(b.mine)).map(b=>id(b.mine)));
const needMiningBase=postOpening && healthyMines.size<miningGoal;
const startMiningBase=needMiningBase && bases.every(b=>b.finished);
const finishedSites=bases.filter(b=>b.finished && b.mine);
let miningSites=finishedSites.concat(safeBases.filter(b=>b.remote));
if(postOpening) {
  // Keep the depleted line working until its replacement is available.
  const byMine=new Map();
  const safeIds=new Set(safeBases.map(b=>b.id));
  miningSites.sort((a,b)=>Number(!safeIds.has(a.id))-Number(!safeIds.has(b.id)) ||
    Number(lowMine(a.mine))-Number(lowMine(b.mine)) || a.id-b.id);
  for(const b of miningSites) if(!byMine.has(id(b.mine))) byMine.set(id(b.mine),b);
  miningSites=Array.from(byMine.values()).slice(0,miningGoal);
  safeBases=safeBases.filter(b=>miningSites.some(site=>site.id===b.id));
}

// All repeated orders pass through a short deterministic lease, avoiding order oscillation.
function order(name, units, target, seconds) {
  for (const u of units) {
    const key = name + ':' + (target && target.unit ? id(target.unit) : target ? Math.round(target.x*2)+','+Math.round(target.y*2) : '');
    const previous = S.orders[id(u)];
    if (previous && previous.key === key && now-previous.time < (seconds || 3)) continue;
    scope.order(name,[u],target);
    S.orders[id(u)] = {key,time: now};
  }
}
function move(u, point, command) {
  const p = reachableFrom(u,point.x,point.y);
  if (p) order(command || 'Move',[u],p,3);
}
function builderNear(point, allowScout) {
  return workers.filter(w => !usedWorkers[id(w)] && (allowScout || id(w)!==S.scoutId) &&
    !Object.values(S.pending).some(p => p.worker===id(w)) &&
    !Object.values(S.repairs).some(r => r.worker===id(w)) &&
    !/^Build |^Repair$/.test(w.getCurrentOrderName() || '') && onWalkableField(w))
    .sort((a,b) => dist(pos(a),point)-dist(pos(b),point) || id(a)-id(b))[0];
}

// Reconcile actual investments, pending orders and stopped construction each update.
buildings.forEach(b => {
  const key = id(b), old = S.investments[key], left = b.getValue('buildTicksLeft');
  if (!old) S.investments[key] = {type:b.getTypeName(), status:'pending', lastProgress:now, left};
  const record = S.investments[key];
  if (record.left !== left) {
    record.lastProgress = now;
    delete record.waitingForDefense;
  }
  record.left = left; record.status = b.isUnderConstruction() ? 'pending' : 'completed';
  if (!b.isUnderConstruction()) { delete S.repairs[key]; return; }
  if (now-record.lastProgress >= C.stalledBuildSeconds) {
    const previous = S.repairs[key];
    // A stalled expansion can keep drawing fresh miners into the same raid.
    // Resume after a clear observation, a short memory timeout, or the arrival of guards.
    if(b.getTypeName()==='Castle') {
      const site=pos(b);
      const pressure=memory.filter(e=>!e.building&&e.type!=='Worker'&&e.damage>0&&!e.lastPositionCleared&&
        now-e.seen<25&&dist(e,site)<13)
        .reduce((sum,e)=>sum+P.power(e),0);
      const cover=observations.filter(u=>u.type!=='Worker'&&u.damage>0&&dist(u,site)<12)
        .reduce((sum,u)=>sum+P.power(u),0);
      if(pressure>0 && pressure*C.defenseMargin>cover) {
        record.waitingForDefense=true;
        const returning=previous&&byID[previous.worker];
        if(returning) { move(returning,home); usedWorkers[id(returning)]=true; }
        delete S.repairs[key];
        S.stats.deferredCastleRepairs=(S.stats.deferredCastleRepairs||0)+1;
        return;
      }
    }
    let w = previous && byID[previous.worker];
    if (!w || now-previous.time > C.buildRetrySeconds) w = builderNear(pos(b));
    if (w) {
      order('Repair',[w],{unit:b},4); usedWorkers[id(w)] = true;
      S.repairs[key] = {worker:id(w),time:now}; record.lastProgress = now;
      S.stats.recoveredBuilds++;
    }
  }
});
Object.keys(S.investments).forEach(key => {
  const r=S.investments[key];
  if (!byID[key] && r.status!=='lost') { r.status='lost'; r.lostAt=now; S.stats.lostBuildings++; delete S.repairs[key]; }
});
Object.keys(S.pending).forEach(type => {
  const p = S.pending[type];
  const appeared = typed(type).some(b => { const q=b.getBuildPosition(); return q.x===p.x&&q.y===p.y; });
  if (appeared) { delete S.pending[type]; return; }
  const builder=byID[p.worker], active=builder && builder.getCurrentOrderName()==='Build '+type;
  if(active) {
    const d=dist(pos(builder),p);
    if(p.bestDistance===undefined || d+1<p.bestDistance) { p.bestDistance=d; p.lastProgress=now; }
  }
  let retry=C.buildRetrySeconds;
  if(type==='House' && capacity-supply<=4) retry=Math.min(retry,8);
  if(active && dist(pos(builder),p)<5) retry=Math.min(retry,C.stalledBuildSeconds+1);
  if (!builder || (!active && now-p.time>2) || now-(p.lastProgress||p.time)>retry) {
    if (active) order('Stop',[builder],null,1);
    delete S.pending[type]; S.stats.failedBuilds++; S.spotTry+=7;
  } else usedWorkers[p.worker]=true;
});

const enemyStarts=scope.getArrayOfPlayerNumbers().filter(n=>scope.getTeamNumber(n)!==scope.getMyTeamNumber()&&scope.getTeamNumber(n)!==0)
  .map(n=>scope.getStartLocationForPlayerNumber(n)).filter(Boolean);
const earlyDens=C.emergencySecondBarracks && now<165 && memory.filter(e=>e.type==='Wolves Den'&&now-e.seen<60).length>=2;
function crowdsRamp(x,y,size) {
  const cache=S.rampSites||(S.rampSites={});
  const key=x+','+y+','+size;
  if(cache[key]!==undefined) return cache[key];
  const gap=C.rampClearance;
  for(let tx=x-gap;tx<x+size+gap;tx++) {
    for(let ty=y-gap;ty<y+size+gap;ty++) {
      if(scope.fieldIsRamp(tx,ty)) return cache[key]=true;
    }
  }
  return cache[key]=false;
}

let castleSurvey=null, castleReserve=0;
function onFootprint(a,p,size) {
  return a.x>=p.x-1-a.radius && a.x<=p.x-1+size+a.radius &&
    a.y>=p.y-1-a.radius && a.y<=p.y-1+size+a.radius;
}
function canClearSite(a) {
  return !a.building && !a.flying && a.speed>0 &&
    !/^Build |^Repair$/.test(byID[a.id].getCurrentOrderName()||'');
}

function placement(type,base) {
  const size = scope.getTypeFieldValue(type.toLowerCase(),'size') || 3;
  let anchors = bases.length ? bases.map(b => ({x:b.x,y:b.y})) : [home];
  if (base) anchors=[base];
  if (type==='Watchtower' && base && base.mine) {
    const mine=pos(base.mine);
    anchors=[{x:(base.x+mine.x)/2,y:(base.y+mine.y)/2}];
  }
  if(type!=='Castle'&&anchors.length>1) {
    const offset=Math.floor(now/8)%anchors.length;
    anchors=anchors.slice(offset).concat(anchors.slice(0,offset));
  }
  if (type==='Castle') {
    anchors = mines.filter(m => surveySafe(m) && (!postOpening || !lowMine(m)) && S.surveyedMines[id(m)]?.available && now-S.surveyedMines[id(m)].time<75 && !bases.some(b => dist(b,pos(m))<14) &&
      !memory.some(e => dist(e,pos(m)) < (e.building ? 13 : 10))).map(m => ({...pos(m),mine:id(m)}));
    anchors.sort((a,b) => dist(a,home)-dist(b,home) || a.mine-b.mine);
    if(anchors.length>1) {
      const offset=Math.floor(now/8)%anchors.length;
      anchors=anchors.slice(offset).concat(anchors.slice(0,offset));
    }
  }
  let attempts=0;
  for (const a of anchors) {
    const secondCastle=type==='Castle'&&bases.length===1;
    const towardHome=secondCastle?Math.atan2(home.y-a.y,home.x-a.x):0;
    // Ring enumeration varies after failed orders, with a strict placement work budget.
    for (let j=0;j<160;j++) {
      if (++attempts>C.placementBudget) return null;
      const k=(j+S.spotTry)%160, ring=type==='Castle' ? 9+Math.floor(k/32) :
        type==='Watchtower' ? 3+Math.floor(k/20) : 6+Math.floor(k/20)*2;
      const n=type==='Castle'?32:20,index=k%n;
      const offset=secondCastle?Math.ceil(index/2)*(index%2?1:-1):index;
      const angle=towardHome+offset*Math.PI*2/n;
      const p={x:Math.round(a.x+Math.cos(angle)*ring-size/2),y:Math.round(a.y+Math.sin(angle)*ring-size/2)};
      if(secondCastle&&bases[0].mine) {
        const center={x:p.x-1+size/2,y:p.y-1+size/2};
        if(dist(center,pos(bases[0].mine))<=dist(center,a)) continue;
      }
      if (type==='Watchtower' && base && base.mine) {
        const mine=pos(base.mine), dx=mine.x-base.x,dy=mine.y-base.y;
        const t=Math.max(0,Math.min(1,((p.x+size/2-base.x)*dx+(p.y+size/2-base.y)*dy)/Math.max(1,dx*dx+dy*dy)));
        if(dist({x:p.x+size/2,y:p.y+size/2},{x:base.x+t*dx,y:base.y+t*dy})<2.5) continue;
      }
      if (p.x<2||p.y<2||p.x+size>=scope.getMapWidth()||p.y+size>=scope.getMapHeight()) continue;
      // Keep each expansion on its gold mine's level.
      if(type==='Castle' && scope.getHeightLevel(p.x-1+size/2,p.y-1+size/2)!==scope.getHeightLevel(a.x,a.y)) continue;
      if (!scope.canSeeField(p.x,p.y) || !scope.canSeeField(p.x+size-1,p.y+size-1) ||
          (type==='Castle' && (!scope.canSeeField(p.x+size-1,p.y)||!scope.canSeeField(p.x,p.y+size-1)))) {
        if(type==='Castle' && (secondCastle || S.commander?.objective==='expand') && !castleSurvey && S.surveyMine===a.x+','+a.y && !crowdsRamp(p.x,p.y,size) &&
           !(S.surveySkip?.until>now && S.surveySkip.x===p.x && S.surveySkip.y===p.y)) {
          castleSurvey={x:p.x,y:p.y,mine:S.surveyMine,size};
        }
        continue;
      }
      if (Object.values(S.pending).some(q => dist(p,q)<size+3)) continue;
      // Leave traversable production exits instead of eventually walling the army in.
      if(buildings.some(b=>{
        const q=b.getBuildPosition(),n=b.getFieldValue('size'),gap=C.buildingGap;
        return !(p.x+size+gap<=q.x||q.x+n+gap<=p.x||p.y+size+gap<=q.y||q.y+n+gap<=p.y);
      })) continue;
      if (!scope.canBuildAt(p.x,p.y,type.toLowerCase()) || crowdsRamp(p.x,p.y,size)) continue;
      const w=builderNear(p,type==='Castle');
      if (!w) return null;
      // The engine only pushes idle blockers. Miners crossing a House site can
      // keep its builder waiting even after it reaches the footprint.
      if(observations.some(u=>!u.building && u.id!==id(w) && (u.type!=='Worker'||type==='House') &&
        onFootprint(u,p,size) && !(type==='Castle' && S.commander?.objective==='expand' && canClearSite(u)))) continue;
      const edgePoint=reachableFrom(w,p.x-1,p.y-1);
      if (!edgePoint || dist(edgePoint,p)>4 || !scope.isReachable(Math.ceil(w.getX()),Math.ceil(w.getY()),edgePoint.x,edgePoint.y)) continue;
      if (type==='Castle') {
        const mineEdge=reachableFrom(w,a.x-3,a.y);
        if (!mineEdge || dist(mineEdge,a)>5 || scope.getGroundDistance(edgePoint.x,edgePoint.y,mineEdge.x,mineEdge.y)>18) continue;
      }
      return {...p,worker:w};
    }
  }
  return null;
}
function ensure(type,count,base) {
  if (typed(type).length>=count || S.pending[type]) return true;
  if ((type==='Barracks'||type==='Workshop')&&!done('House').length) { blocking='waiting for finished House'; return false; }
  const site=placement(type,base);
  if (!site) { blocking='no visible safe reachable site / builder for '+type; return false; }
  if(type==='Castle') S.viableExpansion={x:site.x+1.5,y:site.y+1.5,time:now};
  const price=cost(type);
  if (budget-(type==='Castle'?0:castleReserve)<price) { reserved=Math.max(reserved,price); blocking='saving '+price+' gold for '+type; return false; }
  scope.order('Build '+type,[site.worker],site);
  if (id(site.worker)===S.scoutId) { S.scoutId=null; S.nextScout=now+C.scoutFrequency; }
  S.pending[type]={x:site.x,y:site.y,worker:id(site.worker),time:now};
  if(type==='Castle') castleReserve=0;
  purchases.push(type);
  usedWorkers[id(site.worker)]=true; budget-=price; return true;
}

const chat = scope.chatMessages || [];
const selectRaiders = chat.some(({text, timeSeconds, playerName}) => {
  if (timeSeconds >= 10 || text.trim().toLowerCase() !== 'venibot raiders') return false;
  return game.players.some(p => p?.name === playerName && p.isAlive && p.team.number !== scope.getMyTeamNumber() &&
      (p.controller === CONTROLLER.HUMAN || p.controller === CONTROLLER.REMOTE));
});
if (!S.raiderOpening && (C.forceRaiderOpening || selectRaiders)) {
  S.raiderOpening = true;
  if (!C.forceRaiderOpening) scope.chatMsg('Venibot: one-base Raiders selected.');
}
// Build a defensive firing position while there is still an army to cover its builder.
const raided=bases.filter(b=>b.finished && b.threats.filter(e=>e.seen===now&&!e.building&&e.type!=='Worker'&&dist(e,b)<16).length>=2)
  .sort((a,b)=>b.threat-a.threat||a.id-b.id)[0];
const defence = defendAssets();
const assetGuards = defence.assigned;
if (assetGuards.has(S.scoutId) || defence.managedWorkers.has(S.scoutId)) S.scoutId=null;
if (S.raiderOpening) {
  runRaiderOpening();
  sevenHandleChat(chat, 'raiders', sevenRaiderReports);
  return;
}

// Completed milestones unlock later phases, while current target counts repair losses.
const phaseNames=['first Barracks','second base','Workshop + second Barracks','third base','three-base production','main attack','mining expansions'];
let advance=false;
if (S.phase===0) advance=done('Barracks').length>=1;
if (S.phase===1) advance=done('Castle').length>=2;
if (S.phase===2) advance=done('Workshop').length>=1&&done('Barracks').length>=2;
if (S.phase===3) advance=done('Castle').length>=3;
if(S.phase>=4 && done('Castle').length>=3 && workers.length>=3*C.workersPerMine) S.filledThreeBases=true;
// Once truly capped, staffing up for extra production may require combat losses.
if (S.phase===4) advance=done('Barracks').length>=C.threeBaseBarracks ||
  (supply>=cap && done('Castle').length>=3);
if (S.phase===5) advance=S.firstAttackAt!==undefined || needMiningBase;
if (advance) { S.phase++; S.phaseHistory.push({phase:S.phase,time:now}); }
const targets={Castle:postOpening?Math.max(3,bases.length+Number(startMiningBase)):S.phase>=3?3:S.phase>=1?2:1,Barracks:S.phase>=4?C.threeBaseBarracks:S.phase>=2?2:1,Workshop:S.phase>=2?1:0};
const openingCastle=bases.find(b=>!b.finished && bases.length===2 && S.phase===1);
if(openingCastle) S.naturalId=openingCastle.id;
if(S.naturalId && !byID[S.naturalId]) {
  if(bases.length===1) S.retakeNatural=true;
  delete S.naturalId; delete S.naturalHold;
}
if(done('Castle').length>=2) S.retakeNatural=false;
const preparingThird=S.phase===3 && typed('Castle').length===2 && done('Workshop').length>0 &&
  !army.some(u=>u.getTypeName()==='Catapult') &&
  !done('Workshop').some(b=>b.getUnitTypeNameInProductionQueAt(1)==='Catapult');
const saveFirstCat=preparingThird && !emergency && army.filter(u=>u.getTypeName()==='Archer').length>=C.archersPerCatapult;
const castleHousing=typed('Castle').filter(b=>b.isUnderConstruction() &&
  b.getValue('buildTicksLeft')<=scope.getTypeFieldValue('house','buildTime')).length*scope.getTypeFieldValue('castle','supplyProvided');
const pendingSupply=typed('House').filter(b=>b.isUnderConstruction()).length*10+(S.pending.House?10:0)+castleHousing;
// Keep mining while the first surveyor/builder leaves, and prepare transfers as soon
// as the next Castle is paid for. A Castle takes two worker training cycles to finish.
const incomingMines=bases.filter(b=>!b.finished&&b.mine&&!S.investments[b.id]?.waitingForDefense).length;
const surveyWorker=S.phase===1 && bases.length===1 && !emergency?1:0;
const firstNatural=S.phase<=1 && typed('Barracks').length<=1 && !S.retakeNatural && !(C.emergencySecondBarracks && S.rushDefenseUntil>now);
const savingForFirstNatural=firstNatural && bases.length===1 && !S.pending.Castle;
const workerTarget=savingForFirstNatural?12:Math.min(C.maxWorkers,Math.max(C.workerPriorityFloor,
  (safeBases.length+incomingMines)*C.workersPerMine+surveyWorker));
// Cover the next production cycles while a worker travels and builds the House.
const supplyRate=(producer,unit)=>done(producer).length*scope.getTypeFieldValue(unit,'supply')*
  20/Math.max(1,scope.getTypeFieldValue(unit,'buildTime'));
const trainingWorkers=workers.length<workerTarget;
const supplyBuffer=Math.max(3,Math.ceil(C.housingLeadSeconds*(supplyRate('Barracks','archer')+
  supplyRate('Workshop','catapult')+(trainingWorkers?supplyRate('Castle','worker'):0))));
// The second Castle also supplies housing. With room for an Archer and a surveyed
// natural, keep its 350 gold ahead of an early second House.
if(S.commander?.objective==='expand' && !raided && !emergency && !S.pending.Castle && bases.length<targets.Castle) castleReserve=cost('Castle');
const naturalHousing=firstNatural && done('Castle').length===1 && typed('House').length>=1;
if (!typed('House').length || (!naturalHousing && capacity+pendingSupply<cap && capacity+pendingSupply-supply<supplyBuffer)) ensure('House',typed('House').length+1);
// Two working Barracks can spend every delivery while vision of a Castle footprint
// flickers. Keep the price available during a short, adequately defended survey.
